fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            let lines: Vec<String> = if keepends {
                s.split('\n')
                    .map(|line| line.to_string() + "\n") // Retain line endings
                    .collect()
            } else {
                s.split('\n')
                    .map(|line| line.to_string()) // Do not retain line endings
                    .collect()
            };
            // Ensure that the inner list is non-empty
            if lines.is_empty() {
                vec![String::new()] // Placeholder to ensure non-empty inner list
            } else {
                lines
            }
        })
        .collect()
}